files.editor/capabilities.py:
"""Immutable capability declarations shared by every editor front end."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass, field, replace
from types import MappingProxyType

from .capability_types import CapabilityMaturity, CapabilitySupport
from .equipment import EquipmentSupport

# The owner accepted the three installed original X-Ray releases after loading
# the edited copies in each official game and confirming the visible result.
# S.T.A.L.K.E.R. 2 and Enhanced Editions remain gated until their own local
# samples exist.  This set is evidence ownership, not a second app/release
# registry: app IDs and paths stay in editor.releases.
_GAMEPLAY_VERIFIED_RELEASES: frozenset[str] = frozenset(
    {"stalker-soc", "stalker-cs", "stalker-cop"}
)
_MUTATION_CAPABILITY_FIELDS = (
    "edit_money",
    "edit_stacks",
    "move_items",
    "add_items",
    "remove_items",
    "edit_durability",
    "edit_upgrades",
    "edit_relations",
    "edit_player_faction",
    "edit_placement",
)
_UNSUPPORTED = CapabilitySupport("unsupported")


@dataclass(frozen=True)
class FormatCapabilities:
    """Describe format edits through one maturity model.

    The ``edit_*`` attributes are compatibility projections.  They are not
    stored state and can never disagree with ``mutation_support``: only
    ``experimental`` and ``verified`` maturity is writable.
    """

    read_inventory: bool = False
    catalog: bool = False
    equipment: EquipmentSupport | None = None
    mutation_support: Mapping[str, CapabilitySupport] = field(default_factory=dict)

    def __post_init__(self) -> None:
        raw = dict(self.mutation_support)
        unknown = set(raw) - set(_MUTATION_CAPABILITY_FIELDS)
        if unknown:
            names = ", ".join(sorted(str(value) for value in unknown))
            raise ValueError(f"unknown capability in mutation_support: {names}")
        for field_name, support in raw.items():
            if not isinstance(support, CapabilitySupport):
                raise TypeError(
                    f"mutation_support[{field_name!r}] must be CapabilitySupport"
                )
        normalized = {
            field_name: raw.get(field_name, _UNSUPPORTED)
            for field_name in _MUTATION_CAPABILITY_FIELDS
        }
        object.__setattr__(self, "mutation_support", MappingProxyType(normalized))

    def support(self, field_name: str) -> CapabilitySupport:
        """Return one mutation maturity or reject a misspelled field."""

        if field_name not in _MUTATION_CAPABILITY_FIELDS:
            raise KeyError(f"unknown mutation capability: {field_name!r}")
        return self.mutation_support[field_name]

    @property
    def experimental_fields(self) -> frozenset[str]:
        """Return experimental fields as a computed compatibility projection."""

        return frozenset(
            field_name
            for field_name in _MUTATION_CAPABILITY_FIELDS
            if self.support(field_name).maturity == "experimental"
        )

    def is_experimental(self, field_name: str) -> bool:
        """Return whether one enabled edit needs an explicit UI warning."""

        return self.support(field_name).maturity == "experimental"

    @property
    def edit_money(self) -> bool:
        return self.support("edit_money").writable

    @property
    def edit_stacks(self) -> bool:
        return self.support("edit_stacks").writable

    @property
    def move_items(self) -> bool:
        return self.support("move_items").writable

    @property
    def add_items(self) -> bool:
        return self.support("add_items").writable

    @property
    def remove_items(self) -> bool:
        return self.support("remove_items").writable

    @property
    def edit_durability(self) -> bool:
        return self.support("edit_durability").writable

    @property
    def edit_upgrades(self) -> bool:
        return self.support("edit_upgrades").writable

    @property
    def edit_relations(self) -> bool:
        return self.support("edit_relations").writable

    @property
    def edit_player_faction(self) -> bool:
        return self.support("edit_player_faction").writable

    @property
    def edit_placement(self) -> bool:
        return self.support("edit_placement").writable

    def as_dict(self) -> dict[str, object]:
        """Return the canonical JSON projection shared by Qt, web and CLI."""

        payload: dict[str, object] = {
            "read_inventory": self.read_inventory,
            "catalog": self.catalog,
            "equipment": self.equipment.as_dict() if self.equipment is not None else None,
            "mutation_support": {
                field_name: self.support(field_name).as_dict()
                for field_name in _MUTATION_CAPABILITY_FIELDS
            },
            # Keep the established web/UI contract while deriving every bool.
            "experimental_fields": sorted(self.experimental_fields),
        }
        payload.update(
            {
                field_name: getattr(self, field_name)
                for field_name in _MUTATION_CAPABILITY_FIELDS
            }
        )
        return payload


def gameplay_verified_release_ids() -> frozenset[str]:
    """Return releases with an accepted M10 load/re-save result."""

    return _GAMEPLAY_VERIFIED_RELEASES


def gate_mutations_for_release(
    release_id: str,
    capabilities: FormatCapabilities,
) -> FormatCapabilities:
    """Keep unverified release mutations read-only.

    The parser can still be used by the M10 preparation tool through the
    format writer.  This gate controls user-facing capability metadata only,
    so a local synthetic test cannot be mistaken for game evidence.
    """

    if release_id in _GAMEPLAY_VERIFIED_RELEASES:
        return capabilities
    downgraded: dict[str, CapabilitySupport] = {}
    for field_name in _MUTATION_CAPABILITY_FIELDS:
        support = capabilities.support(field_name)
        if support.maturity == "verified":
            downgraded[field_name] = CapabilitySupport(
                "research",
                support.reason
                or "game load/re-save evidence is not accepted for this release",
            )
        else:
            downgraded[field_name] = support
    return replace(capabilities, mutation_support=downgraded)


__all__ = [
    "CapabilityMaturity",
    "CapabilitySupport",
    "FormatCapabilities",
    "gameplay_verified_release_ids",
    "gate_mutations_for_release",
]

files.editor/capability_types.py:
"""Shared evidence maturity type for every user-facing mutation capability."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

CapabilityMaturity = Literal["unsupported", "research", "experimental", "verified"]


@dataclass(frozen=True)
class CapabilitySupport:
    """One capability's evidence maturity and the reason shown to users."""

    maturity: CapabilityMaturity
    reason: str | None = None

    def __post_init__(self) -> None:
        if self.maturity not in {
            "unsupported",
            "research",
            "experimental",
            "verified",
        }:
            raise ValueError(f"unsupported maturity: {self.maturity!r}")
        if self.reason is not None:
            normalized = str(self.reason).strip()
            object.__setattr__(self, "reason", normalized or None)

    @property
    def writable(self) -> bool:
        """Return whether the operation may be staged by a source-backed writer."""

        return self.maturity in {"experimental", "verified"}

    def as_dict(self) -> dict[str, str | None]:
        """Return the stable JSON projection used by Qt/web/CLI adapters."""

        return {"maturity": self.maturity, "reason": self.reason}


__all__ = ["CapabilityMaturity", "CapabilitySupport"]

files.editor/catalog.py:
"""Source-independent item catalog models.

Catalog entries are deliberately separate from save parsing.  A serialized
object key is useful for diagnostics, but it is not a SID or a proof that an
item can be constructed in a save.  The ``source`` field keeps that boundary
visible to every front end.
"""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass
from pathlib import Path
from typing import Protocol

from .releases import ReleaseDescriptor


class CatalogLookupError(LookupError):
    """An exact catalog key is not present in the selected release."""


@dataclass(frozen=True)
class FactionDefinition:
    """One community identifier read from an official X-Ray resource."""

    key: str
    display_name: str | None
    source: str
    release_id: str
    numeric_id: int | None = None

    def __post_init__(self) -> None:
        if not self.key.strip():
            raise ValueError("faction key must not be empty")
        if not self.source.strip():
            raise ValueError("faction source must not be empty")
        if not self.release_id.strip():
            raise ValueError("faction release_id must not be empty")
        if self.display_name is not None:
            object.__setattr__(self, "display_name", self.display_name.strip() or None)
        if self.numeric_id is not None and self.numeric_id < 0:
            raise ValueError("faction numeric_id must not be negative")


@dataclass(frozen=True)
class FactionCatalog:
    """Immutable, release-scoped X-Ray community catalog.

    ``relations`` contains defaults from ``[communities_relations]``.  They
    describe resource defaults only; they are deliberately not presented as
    the current relation values from a save until a save codec proves that
    distinction.
    """

    release_id: str
    source_root: Path | None
    factions: tuple[FactionDefinition, ...]
    relations: tuple[tuple[str, str, int], ...] = ()
    goodwill_min: int | None = None
    goodwill_max: int | None = None
    attitude_neutral_threshold: int | None = None
    attitude_friend_threshold: int | None = None

    def __post_init__(self) -> None:
        if not self.release_id.strip():
            raise ValueError("faction catalog release_id must not be empty")
        factions = tuple(self.factions)
        keys = [faction.key for faction in factions]
        if len(keys) != len(set(keys)):
            raise ValueError("duplicate faction key in catalog")
        if any(faction.release_id != self.release_id for faction in factions):
            raise ValueError("faction release_id does not match catalog release_id")
        relation_values = tuple(
            (str(source), str(target), int(value))
            for source, target, value in self.relations
        )
        known = set(keys)
        if any(source not in known or target not in known for source, target, _ in relation_values):
            raise ValueError("faction relation references an unknown community")
        if len({(source, target) for source, target, _ in relation_values}) != len(relation_values):
            raise ValueError("duplicate faction relation in catalog")
        numeric_ids = tuple(
            faction.numeric_id for faction in factions if faction.numeric_id is not None
        )
        if len(numeric_ids) != len(set(numeric_ids)):
            raise ValueError("duplicate faction numeric_id in catalog")
        for field_name in (
            "goodwill_min",
            "goodwill_max",
            "attitude_neutral_threshold",
            "attitude_friend_threshold",
        ):
            value = getattr(self, field_name)
            if value is not None and (not isinstance(value, int) or isinstance(value, bool)):
                raise TypeError(f"{field_name} must be an int or None")
        if (
            self.goodwill_min is not None
            and self.goodwill_max is not None
            and self.goodwill_min > self.goodwill_max
        ):
            raise ValueError("goodwill_min must not exceed goodwill_max")
        object.__setattr__(self, "factions", factions)
        object.__setattr__(self, "relations", relation_values)
        if self.source_root is not None:
            object.__setattr__(self, "source_root", Path(self.source_root))

    def resolve(self, key: str) -> FactionDefinition:
        """Resolve an exact community key or refuse the foreign/missing key."""

        for faction in self.factions:
            if faction.key == key:
                return faction
        raise CatalogLookupError(
            f"faction key {key!r} отсутствует в catalog release {self.release_id!r}"
        )

    def resolve_numeric(self, numeric_id: int) -> FactionDefinition | None:
        """Resolve an engine community index without inventing a key."""

        if not isinstance(numeric_id, int) or isinstance(numeric_id, bool):
            return None
        return next(
            (faction for faction in self.factions if faction.numeric_id == numeric_id),
            None,
        )

    def relation_address(self, source: str, target: str) -> tuple[int, int]:
        """Return the engine's row/column address for two exact keys."""

        source_faction = self.resolve(source)
        target_faction = self.resolve(target)
        if source_faction.numeric_id is None or target_faction.numeric_id is None:
            raise CatalogLookupError(
                f"catalog release {self.release_id!r} has no numeric relation address "
                f"for {source!r} -> {target!r}"
            )
        return source_faction.numeric_id, target_faction.numeric_id

    def default_relation(self, source: str, target: str) -> int | None:
        """Return a resource default, never a current save value."""

        self.resolve(source)
        self.resolve(target)
        for relation_source, relation_target, value in self.relations:
            if relation_source == source and relation_target == target:
                return value
        return None

    @property
    def relation_addresses(self) -> tuple[tuple[str, str, int, int, int], ...]:
        """Return serializable resource relation metadata in catalog order."""

        rows: list[tuple[str, str, int, int, int]] = []
        for source, target, value in self.relations:
            row, column = self.relation_address(source, target)
            rows.append((source, target, row, column, value))
        return tuple(rows)


@dataclass(frozen=True)
class UpgradeDefinition:
    """One selectable equipment/weapon upgrade from an official X-Ray LTX."""

    key: str
    display_name: str | None
    category: str | None
    item_key: str | None
    source: str
    release_id: str
    section: str | None = None
    property_name: str | None = None
    icon: str | None = None
    applicable_item_keys: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not self.key.strip():
            raise ValueError("upgrade key must not be empty")
        if not self.source.strip():
            raise ValueError("upgrade source must not be empty")
        if not self.release_id.strip():
            raise ValueError("upgrade release_id must not be empty")
        for field_name in ("display_name", "item_key", "section", "property_name", "icon"):
            value = getattr(self, field_name)
            if value is not None:
                object.__setattr__(self, field_name, value.strip() or None)
        applicable = tuple(
            dict.fromkeys(
                str(value).strip()
                for value in self.applicable_item_keys
                if str(value).strip()
            )
        )
        if self.item_key is not None and self.item_key not in applicable:
            applicable = (self.item_key, *applicable)
        object.__setattr__(self, "applicable_item_keys", applicable)

    def applies_to(self, item_key: str) -> bool:
        """Return whether official resource metadata names this exact item."""

        return item_key in self.applicable_item_keys


@dataclass(frozen=True)
class UpgradeCatalog:
    """Immutable, release-scoped upgrade definitions from official resources."""

    release_id: str
    source_root: Path | None
    upgrades: tuple[UpgradeDefinition, ...]

    def __post_init__(self) -> None:
        if not self.release_id.strip():
            raise ValueError("upgrade catalog release_id must not be empty")
        upgrades = tuple(self.upgrades)
        keys = [upgrade.key for upgrade in upgrades]
        if len(keys) != len(set(keys)):
            raise ValueError("duplicate upgrade key in catalog")
        if any(upgrade.release_id != self.release_id for upgrade in upgrades):
            raise ValueError("upgrade release_id does not match catalog release_id")
        object.__setattr__(self, "upgrades", upgrades)
        if self.source_root is not None:
            object.__setattr__(self, "source_root", Path(self.source_root))

    def resolve(self, key: str) -> UpgradeDefinition | None:
        """Resolve an exact serialized upgrade id."""

        return next((upgrade for upgrade in self.upgrades if upgrade.key == key), None)

    def for_item(self, item_key: str) -> tuple[UpgradeDefinition, ...]:
        """Return only upgrades whose resource source names this exact item."""

        return tuple(
            upgrade
            for upgrade in self.upgrades
            if upgrade.applies_to(item_key)
        )


@dataclass(frozen=True)
class GameCatalog:
    """The item, upgrade and faction catalogs for exactly one release."""

    release_id: str
    items: ItemCatalog
    factions: FactionCatalog
    upgrades: UpgradeCatalog | None = None

    def __post_init__(self) -> None:
        if not self.release_id.strip():
            raise ValueError("game catalog release_id must not be empty")
        if self.items.release_id != self.release_id:
            raise ValueError("item catalog release_id does not match game catalog")
        if self.factions.release_id != self.release_id:
            raise ValueError("faction catalog release_id does not match game catalog")
        if self.upgrades is not None and self.upgrades.release_id != self.release_id:
            raise ValueError("upgrade catalog release_id does not match game catalog")


@dataclass(frozen=True)
class ItemDefinition:
    """One item definition read from an official release resource tree."""

    key: str
    display_name: str | None
    category: str | None
    unit_weight: float | None
    width: int | None
    height: int | None
    max_stack: int | None
    slots: tuple[str, ...]
    prototype: bytes | None
    source: str
    class_name: str | None = None
    serialization_family: str | None = None
    icon_x: int | None = None
    icon_y: int | None = None
    icon_texture: str | None = None

    def __post_init__(self) -> None:
        if not self.key.strip():
            raise ValueError("item key must not be empty")
        if not self.source.strip():
            raise ValueError("item source must not be empty")
        if self.class_name is not None:
            object.__setattr__(self, "class_name", self.class_name.strip() or None)
        if self.serialization_family is not None:
            family = self.serialization_family.strip().casefold()
            object.__setattr__(self, "serialization_family", family or None)
        if self.icon_texture is not None:
            texture = self.icon_texture.strip().replace("\\", "/")
            object.__setattr__(self, "icon_texture", texture or None)
        object.__setattr__(self, "slots", tuple(str(slot) for slot in self.slots))
        if self.unit_weight is not None and self.unit_weight < 0:
            raise ValueError("item weight must not be negative")
        for field_name in ("width", "height", "max_stack", "icon_x", "icon_y"):
            value = getattr(self, field_name)
            if value is not None and value < 0:
                raise ValueError(f"item {field_name} must not be negative")


@dataclass(frozen=True)
class ItemCatalog:
    """Immutable catalog for one release and one selected resource source."""

    release_id: str
    source_root: Path | None
    items: tuple[ItemDefinition, ...]

    def __post_init__(self) -> None:
        if not self.release_id.strip():
            raise ValueError("catalog release_id must not be empty")
        items = tuple(self.items)
        keys = [item.key for item in items]
        if len(keys) != len(set(keys)):
            raise ValueError("duplicate item key in catalog")
        object.__setattr__(self, "items", items)
        if self.source_root is not None:
            object.__setattr__(self, "source_root", Path(self.source_root))

    def resolve(self, key: str) -> ItemDefinition | None:
        """Return the exact serialized key, without fuzzy/SID guessing."""

        for item in self.items:
            if item.key == key:
                return item
        return None

    def resolve_display_name(self, display_name: str) -> ItemDefinition | None:
        """Resolve one unique official display name without fuzzy matching.

        A save-local name can be useful for presentation, but it must not be
        treated as a prototype SID when several definitions share that label.
        Ambiguous labels therefore return ``None`` and keep the row on the
        category/read-only fallback path.
        """

        normalized = str(display_name).strip().casefold()
        if not normalized:
            return None
        matches = tuple(
            item
            for item in self.items
            if item.display_name is not None
            and item.display_name.strip().casefold() == normalized
        )
        return matches[0] if len(matches) == 1 else None


class CatalogProvider(Protocol):
    """Provider contract used by desktop and future browser catalog loaders."""

    def load(
        self,
        release: ReleaseDescriptor,
        game_root: Path | None = None,
    ) -> ItemCatalog | None:
        """Load a catalog or return ``None`` when evidence is unavailable."""

    def resolve(self, key: str) -> ItemDefinition | None:
        """Resolve against the most recently loaded catalog."""


def catalog_from_items(
    release_id: str,
    items: Sequence[ItemDefinition],
    *,
    source_root: Path | None = None,
) -> ItemCatalog:
    """Small convenience boundary for tests and generated web catalogs."""

    return ItemCatalog(release_id, source_root, tuple(items))


__all__ = [
    "CatalogLookupError",
    "CatalogProvider",
    "FactionCatalog",
    "FactionDefinition",
    "GameCatalog",
    "ItemCatalog",
    "ItemDefinition",
    "UpgradeCatalog",
    "UpgradeDefinition",
    "catalog_from_items",
]

files.editor/catalog_bundle.py:
"""Load the compact official catalog shared by desktop and browser builds.

The generated browser catalog contains metadata derived from official X-Ray
resources, not game files or save bytes.  Keeping its decoder in the editor
package lets the desktop fallback and the browser bridge consume exactly the
same release-scoped data and validation rules.
"""

from __future__ import annotations

import json
import math
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .catalog import (
    FactionCatalog,
    FactionDefinition,
    GameCatalog,
    ItemCatalog,
    ItemDefinition,
    UpgradeCatalog,
    UpgradeDefinition,
    catalog_from_items,
)
from .releases import release_by_id


class CatalogBundleError(ValueError):
    """The generated catalog is malformed or contains foreign metadata."""


@dataclass(frozen=True)
class CatalogBundle:
    """All compact catalogs available for one official release."""

    release_id: str
    items: ItemCatalog
    factions: FactionCatalog | None = None
    upgrades: UpgradeCatalog | None = None

    def __post_init__(self) -> None:
        if self.items.release_id != self.release_id:
            raise CatalogBundleError("item catalog release_id does not match bundle")
        if self.factions is not None and self.factions.release_id != self.release_id:
            raise CatalogBundleError("faction catalog release_id does not match bundle")
        if self.upgrades is not None and self.upgrades.release_id != self.release_id:
            raise CatalogBundleError("upgrade catalog release_id does not match bundle")

    @property
    def game_catalog(self) -> GameCatalog | None:
        """Return the combined catalog only when faction metadata is present."""

        if self.factions is None:
            return None
        return GameCatalog(self.release_id, self.items, self.factions, self.upgrades)


def _optional_str(value: Any, field: str, release_id: str) -> str | None:
    if value is None:
        return None
    if not isinstance(value, str):
        raise CatalogBundleError(f"Browser catalog: invalid {field} for {release_id!r}")
    return value


def _optional_int(value: Any, field: str, release_id: str) -> int | None:
    if value is None:
        return None
    if not isinstance(value, int) or isinstance(value, bool):
        raise CatalogBundleError(f"Browser catalog: invalid {field} for {release_id!r}")
    return value


def _optional_float(value: Any, field: str, release_id: str) -> float | None:
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise CatalogBundleError(f"Browser catalog: invalid {field} for {release_id!r}")
    result = float(value)
    if not math.isfinite(result):
        raise CatalogBundleError(f"Browser catalog: invalid {field} for {release_id!r}")
    return result


def _optional_str_list(value: Any, field: str, release_id: str) -> tuple[str, ...]:
    if value is None:
        return ()
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise CatalogBundleError(f"Browser catalog: invalid {field} for {release_id!r}")
    return tuple(value)


def _document_from_payload(payload: str | bytes | bytearray | Mapping[str, object]) -> Mapping[str, object]:
    if isinstance(payload, Mapping):
        document: Any = payload
    else:
        try:
            source = payload.decode("utf-8") if isinstance(payload, (bytes, bytearray)) else payload
            document = json.loads(source)
        except (UnicodeDecodeError, json.JSONDecodeError, TypeError) as exc:
            raise CatalogBundleError("Некорректный JSON browser catalog") from exc
    if not isinstance(document, Mapping) or document.get("schema_version") != 1:
        raise CatalogBundleError("Некорректная версия browser catalog")
    raw_releases = document.get("releases")
    if not isinstance(raw_releases, Mapping):
        raise CatalogBundleError("Browser catalog не содержит releases")
    return document


def load_catalog_payload(
    payload: str | bytes | bytearray | Mapping[str, object],
    *,
    source_root: Path | None = None,
) -> dict[str, CatalogBundle]:
    """Parse compact metadata and reject foreign release/catalog entries."""

    document = _document_from_payload(payload)
    raw_releases = document["releases"]
    assert isinstance(raw_releases, Mapping)
    loaded: dict[str, CatalogBundle] = {}
    for raw_release_id, raw_release in raw_releases.items():
        release_id = str(raw_release_id)
        try:
            descriptor = release_by_id(release_id)
        except KeyError as exc:
            raise CatalogBundleError(str(exc)) from exc
        if descriptor.edition not in {"original", "s2"}:
            raise CatalogBundleError(f"Browser catalog: unsupported release {release_id!r}")
        if not isinstance(raw_release, Mapping):
            raise CatalogBundleError(f"Browser catalog: invalid release {release_id!r}")

        raw_items = raw_release.get("items")
        if not isinstance(raw_items, list):
            raise CatalogBundleError(f"Browser catalog: invalid items for {release_id!r}")
        definitions: list[ItemDefinition] = []
        for raw_item in raw_items:
            if not isinstance(raw_item, Mapping) or not isinstance(raw_item.get("key"), str):
                raise CatalogBundleError(f"Browser catalog: invalid item for {release_id!r}")
            key = raw_item["key"]
            assert isinstance(key, str)
            definitions.append(
                ItemDefinition(
                    key=key,
                    display_name=_optional_str(
                        raw_item.get("display_name"),
                        "item display_name",
                        release_id,
                    ),
                    category=_optional_str(raw_item.get("category"), "item category", release_id),
                    width=None,
                    height=None,
                    max_stack=_optional_int(raw_item.get("max_stack"), "item max_stack", release_id),
                    slots=_optional_str_list(raw_item.get("slots"), "item slots", release_id),
                    prototype=None,
                    source="generated-official-metadata",
                    # Existing generated catalogs predate S2 resource metadata;
                    # absent fields deliberately keep their old None/default behavior.
                    unit_weight=_optional_float(
                        raw_item.get("unit_weight"),
                        "item unit_weight",
                        release_id,
                    ),
                    serialization_family=_optional_str(
                        raw_item.get("serialization_family"),
                        "item serialization_family",
                        release_id,
                    ),
                    icon_x=_optional_int(raw_item.get("icon_x"), "item icon_x", release_id),
                    icon_y=_optional_int(raw_item.get("icon_y"), "item icon_y", release_id),
                    icon_texture=_optional_str(
                        raw_item.get("icon_texture"),
                        "item icon_texture",
                        release_id,
                    ),
                )
            )
        items = catalog_from_items(release_id, definitions, source_root=source_root)

        factions: FactionCatalog | None = None
        raw_factions = raw_release.get("factions")
        if raw_factions is not None:
            if not isinstance(raw_factions, list):
                raise CatalogBundleError(f"Browser catalog: invalid factions for {release_id!r}")
            faction_definitions: list[FactionDefinition] = []
            for raw_faction in raw_factions:
                if not isinstance(raw_faction, Mapping) or not isinstance(
                    raw_faction.get("key"), str
                ):
                    raise CatalogBundleError(
                        f"Browser catalog: invalid faction for {release_id!r}"
                    )
                faction_key = raw_faction["key"]
                assert isinstance(faction_key, str)
                faction_release_id = raw_faction.get("release_id", release_id)
                if faction_release_id != release_id:
                    raise CatalogBundleError(
                        f"Browser catalog: foreign faction release for {release_id!r}"
                    )
                source = raw_faction.get("source")
                if not isinstance(source, str):
                    raise CatalogBundleError(
                        f"Browser catalog: invalid faction source for {release_id!r}"
                    )
                faction_definitions.append(
                    FactionDefinition(
                        key=faction_key,
                        display_name=_optional_str(
                            raw_faction.get("display_name"),
                            "faction display_name",
                            release_id,
                        ),
                        numeric_id=_optional_int(
                            raw_faction.get("numeric_id"),
                            "faction numeric_id",
                            release_id,
                        ),
                        source=source,
                        release_id=release_id,
                    )
                )

            raw_relations = raw_release.get("relation_addresses", [])
            if not isinstance(raw_relations, list):
                raise CatalogBundleError(
                    f"Browser catalog: invalid relation_addresses for {release_id!r}"
                )
            relations: list[tuple[str, str, int]] = []
            for raw_relation in raw_relations:
                if not isinstance(raw_relation, Mapping):
                    raise CatalogBundleError(
                        f"Browser catalog: invalid faction relation for {release_id!r}"
                    )
                source_key = raw_relation.get("source")
                target_key = raw_relation.get("target")
                value = raw_relation.get("value")
                if (
                    not isinstance(source_key, str)
                    or not isinstance(target_key, str)
                    or not isinstance(value, int)
                    or isinstance(value, bool)
                ):
                    raise CatalogBundleError(
                        f"Browser catalog: invalid faction relation for {release_id!r}"
                    )
                for field in ("row", "column"):
                    _optional_int(raw_relation.get(field), f"relation {field}", release_id)
                relations.append((source_key, target_key, value))

            numeric_fields = {
                field: _optional_int(raw_release.get(field), field, release_id)
                for field in (
                    "goodwill_min",
                    "goodwill_max",
                    "attitude_neutral_threshold",
                    "attitude_friend_threshold",
                )
            }
            factions = FactionCatalog(
                release_id=release_id,
                source_root=source_root,
                factions=tuple(faction_definitions),
                relations=tuple(relations),
                goodwill_min=numeric_fields["goodwill_min"],
                goodwill_max=numeric_fields["goodwill_max"],
                attitude_neutral_threshold=numeric_fields["attitude_neutral_threshold"],
                attitude_friend_threshold=numeric_fields["attitude_friend_threshold"],
            )

        upgrades: UpgradeCatalog | None = None
        raw_upgrades = raw_release.get("upgrades")
        if raw_upgrades is not None:
            if not isinstance(raw_upgrades, list):
                raise CatalogBundleError(f"Browser catalog: invalid upgrades for {release_id!r}")
            upgrade_definitions: list[UpgradeDefinition] = []
            for raw_upgrade in raw_upgrades:
                if not isinstance(raw_upgrade, Mapping) or not isinstance(
                    raw_upgrade.get("key"), str
                ):
                    raise CatalogBundleError(
                        f"Browser catalog: invalid upgrade for {release_id!r}"
                    )
                upgrade_key = raw_upgrade["key"]
                assert isinstance(upgrade_key, str)
                upgrade_release_id = raw_upgrade.get("release_id", release_id)
                if upgrade_release_id != release_id:
                    raise CatalogBundleError(
                        f"Browser catalog: foreign upgrade release for {release_id!r}"
                    )
                source = raw_upgrade.get("source")
                if not isinstance(source, str):
                    raise CatalogBundleError(
                        f"Browser catalog: invalid upgrade source for {release_id!r}"
                    )
                applicable = raw_upgrade.get("applicable_item_keys", [])
                if not isinstance(applicable, list) or not all(
                    isinstance(value, str) for value in applicable
                ):
                    raise CatalogBundleError(
                        f"Browser catalog: invalid upgrade item binding for {release_id!r}"
                    )
                upgrade_definitions.append(
                    UpgradeDefinition(
                        key=upgrade_key,
                        display_name=_optional_str(
                            raw_upgrade.get("display_name"),
                            "upgrade display_name",
                            release_id,
                        ),
                        category=_optional_str(
                            raw_upgrade.get("category"),
                            "upgrade category",
                            release_id,
                        ),
                        item_key=_optional_str(
                            raw_upgrade.get("item_key"),
                            "upgrade item_key",
                            release_id,
                        ),
                        source=source,
                        release_id=release_id,
                        section=_optional_str(
                            raw_upgrade.get("section"),
                            "upgrade section",
                            release_id,
                        ),
                        property_name=_optional_str(
                            raw_upgrade.get("property"),
                            "upgrade property",
                            release_id,
                        ),
                        icon=_optional_str(raw_upgrade.get("icon"), "upgrade icon", release_id),
                        applicable_item_keys=tuple(applicable),
                    )
                )
            upgrades = UpgradeCatalog(release_id, source_root, tuple(upgrade_definitions))

        loaded[release_id] = CatalogBundle(release_id, items, factions, upgrades)
    return loaded


def load_catalog_file(path: Path, *, source_root: Path | None = None) -> dict[str, CatalogBundle]:
    """Read one generated catalog file without exposing its path in entries."""

    try:
        payload = Path(path).read_text(encoding="utf-8")
    except OSError as exc:
        raise CatalogBundleError(f"Не удалось прочитать browser catalog: {path}") from exc
    return load_catalog_payload(payload, source_root=source_root)


__all__ = [
    "CatalogBundle",
    "CatalogBundleError",
    "load_catalog_file",
    "load_catalog_payload",
]

