"""The shared, game-independent part of an original X-Ray save.

The original trilogy stores a little-endian header followed by a raw LZO1X-1
stream.  This module deliberately stops at the container boundary: object
fields and game-specific versions belong to the later format readers.  The
compressor is a small literal-only encoder written from the public format
description.  It is sufficient for safe fixed-size payload edits.  Desktop
systems may use an optional system ``liblzo2`` decoder for large files; the
bounded Python decoder remains the portable and browser implementation.
"""

from __future__ import annotations

import struct
from dataclasses import dataclass
from typing import Any

from save_format import SaveError

try:
    import ctypes
    import ctypes.util
except ImportError:  # pragma: no cover - depends on the Python runtime
    _NATIVE_LZO: Any = None
else:
    _NATIVE_LZO = None
    try:
        _library_name = ctypes.util.find_library("lzo2")
        if _library_name:
            _library = ctypes.CDLL(_library_name)
            _native_lzo = _library.lzo1x_decompress_safe
            _native_lzo.argtypes = [
                ctypes.POINTER(ctypes.c_ubyte),
                ctypes.c_size_t,
                ctypes.POINTER(ctypes.c_ubyte),
                ctypes.POINTER(ctypes.c_size_t),
                ctypes.c_void_p,
            ]
            _native_lzo.restype = ctypes.c_int
            _NATIVE_LZO = _native_lzo
    except (AttributeError, OSError, ValueError):
        # Pyodide and minimal Windows installations do not necessarily expose
        # a shared liblzo2.  The bounded Python decoder below is the portable
        # path and remains the browser implementation.
        _NATIVE_LZO = None

XRAY_MAGIC = 0xFFFFFFFF
XRAY_MAX_UNPACKED_SIZE = 512 * 1024 * 1024
XRAY_SUPPORTED_OUTER_VERSIONS = frozenset({3, 5, 6})
_NATIVE_LZO_MIN_STREAM = 64 * 1024


class XRayError(SaveError):
    """Raised when bytes do not form a supported X-Ray save container."""


def _fail(message: str) -> XRayError:
    return XRayError(f"X-Ray: {message}")


def _literal_length_prefix(length: int) -> bytes:
    if length <= 0:
        return b""
    if length <= 238:
        return bytes((17 + length,))

    value = length - 18
    prefix = bytearray((0,))
    while value > 255:
        prefix.append(0)
        value -= 255
    prefix.append(value)
    return bytes(prefix)


def lzo1x_compress(payload: bytes) -> bytes:
    """Encode ``payload`` as a valid raw LZO1X-1 stream.

    The encoder intentionally emits one literal run and the format's end
    marker.  It does not promise the same compressed bytes as the game's
    dictionary compressor; :class:`XRayContainer` preserves the original
    compressed stream for a no-op round-trip and uses this encoder only after
    an explicit edit.
    """

    data = bytes(payload)
    if not data:
        return b"\x11\x00\x00"
    return _literal_length_prefix(len(data)) + data + b"\x11\x00\x00"


def lzo1x_decompress(stream: bytes, expected_size: int) -> bytes:
    """Decode one raw LZO1X stream with strict input/output bounds."""

    if not isinstance(expected_size, int) or isinstance(expected_size, bool):
        raise _fail("распакованный размер должен быть целым числом")
    if expected_size < 0 or expected_size > XRAY_MAX_UNPACKED_SIZE:
        raise _fail(f"недопустимый распакованный размер: {expected_size}")

    data = bytes(stream)
    if len(data) < 3:
        raise _fail("поток LZO слишком короткий")

    if _NATIVE_LZO is not None and len(data) >= _NATIVE_LZO_MIN_STREAM:
        source = (ctypes.c_ubyte * len(data)).from_buffer_copy(data)
        target = (ctypes.c_ubyte * expected_size)()
        target_size = ctypes.c_size_t(expected_size)
        result = _NATIVE_LZO(
            source,
            len(data),
            target,
            ctypes.byref(target_size),
            None,
        )
        if result != 0:
            raise _fail(f"поток LZO отклонён native decoder: code={result}")
        if target_size.value != expected_size:
            raise _fail(
                f"native decoder вернул размер {target_size.value} вместо {expected_size}"
            )
        return bytes(target)

    ip = 0
    output = bytearray()
    state = 0
    bitstream_version = 0

    # Newer LZO streams may carry a two-byte bitstream marker.  The original
    # X-Ray streams normally use the legacy raw form, but accepting the marker
    # costs nothing and makes malformed-input handling explicit.
    if len(data) >= 5 and data[0] == 17:
        bitstream_version = data[1]
        ip = 2

    def read_u8() -> int:
        nonlocal ip
        if ip >= len(data):
            raise _fail("поток LZO обрезан")
        value = data[ip]
        ip += 1
        return value

    def read_u16() -> int:
        nonlocal ip
        if ip + 2 > len(data):
            raise _fail("поток LZO обрезан на смещении")
        value = struct.unpack_from("<H", data, ip)[0]
        ip += 2
        return value

    def copy_literals(length: int) -> None:
        nonlocal ip
        if length < 0 or ip + length > len(data):
            raise _fail("литеральный участок LZO обрезан")
        if len(output) + length > expected_size:
            raise _fail("распакованный размер превышает заголовок")
        output.extend(data[ip : ip + length])
        ip += length

    def copy_match(start: int, length: int) -> None:
        if length <= 0 or start < 0 or start >= len(output):
            raise _fail("некорректная обратная ссылка LZO")
        if len(output) + length > expected_size:
            raise _fail("распакованный размер превышает заголовок")
        distance = len(output) - start
        # Matches may overlap the write cursor.  Materialising one copy of the
        # already-emitted distance window and repeating it is equivalent to the
        # byte-at-a-time LZ rule, while keeping large real saves practical in
        # the desktop detector and Pyodide browser build.
        pattern = bytes(output[start : start + distance])
        repetitions = (length + distance - 1) // distance
        output.extend((pattern * repetitions)[:length])

    # A first command above 17 is a literal run encoded as 17 + length.  A
    # short run (<4) is followed by the normal match/literal state transition.
    if ip < len(data) and data[ip] > 17:
        first = read_u8() - 17
        copy_literals(first)
        state = first if first < 4 else 4

    while True:
        command = read_u8()

        if command < 16:
            if state == 0:
                length = command
                if length == 0:
                    zeroes = 0
                    while read_u8() == 0:
                        zeroes += 1
                        if zeroes > (XRAY_MAX_UNPACKED_SIZE // 255) + 1:
                            raise _fail("слишком длинный литеральный участок")
                    length = zeroes * 255 + 15 + data[ip - 1]
                copy_literals(length + 3)
                state = 4
                continue

            next_literals = command & 3
            if state != 4:
                match_start = len(output) - 1 - (command >> 2) - (read_u8() << 2)
                copy_match(match_start, 2)
            else:
                match_start = len(output) - (1 + 0x0800) - (command >> 2) - (read_u8() << 2)
                length = 3

            copy_literals(next_literals)
            state = next_literals
            continue

        if command >= 64:
            next_literals = command & 3
            match_start = len(output) - 1 - ((command >> 2) & 7) - (read_u8() << 3)
            length = (command >> 5) + 1
        elif command >= 32:
            length = (command & 31) + 2
            if length == 2:
                zeroes = 0
                while read_u8() == 0:
                    zeroes += 1
                    if zeroes > (XRAY_MAX_UNPACKED_SIZE // 255) + 1:
                        raise _fail("слишком длинная match-длина")
                length += zeroes * 255 + 31 + data[ip - 1]
            encoded = read_u16()
            match_start = len(output) - 1 - (encoded >> 2)
            next_literals = encoded & 3
        else:
            if ip + 2 > len(data):
                raise _fail("поток LZO обрезан на смещении")
            encoded = struct.unpack_from("<H", data, ip)[0]
            next_literals = encoded & 3

            # This optional extension is part of LZO1X bitstream versions that
            # advertise zero runs.  X-Ray does not use it, but rejecting a
            # truncated extension is safer than interpreting it as a match.
            if bitstream_version and (encoded & 0xFFFC) == 0xFFFC and (command & 0xF8) == 0x18:
                read_u16()
                if ip >= len(data):
                    raise _fail("zero-run extension LZO обрезан")
                length = (command & 7) | (read_u8() << 3)
                length += 4
                if len(output) + length > expected_size:
                    raise _fail("нулевой участок превышает размер payload")
                output.extend(b"\x00" * length)
                copy_literals(next_literals)
                state = next_literals
                continue

            length = (command & 7) + 2
            if length == 2:
                zeroes = 0
                while read_u8() == 0:
                    zeroes += 1
                    if zeroes > (XRAY_MAX_UNPACKED_SIZE // 255) + 1:
                        raise _fail("слишком длинная match-длина")
                length += zeroes * 255 + 7 + data[ip - 1]

            encoded = read_u16()
            next_literals = encoded & 3
            if (command & 8) == 0:
                match_start = len(output) - (encoded >> 2)
                if match_start == len(output):
                    if length != 3:
                        raise _fail("неверный LZO end marker")
                    if ip != len(data):
                        raise _fail("после LZO end marker остались байты")
                    break
            else:
                match_start = len(output) - ((command & 8) << 11) - (encoded >> 2)
            match_start -= 0x4000

        copy_match(match_start, length)
        copy_literals(next_literals)
        state = next_literals

    if len(output) != expected_size:
        raise _fail(
            f"неверный размер после распаковки: {len(output)} вместо {expected_size}"
        )
    return bytes(output)


@dataclass(frozen=True)
class XRayChunk:
    """One top-level ``u32 type, u32 size, bytes`` payload chunk."""

    type: int
    offset: int
    size: int
    data: bytes

    @property
    def end(self) -> int:
        return self.offset + 8 + self.size


def parse_chunks(raw: bytes) -> tuple[XRayChunk, ...]:
    """Parse all top-level chunks and reject truncation or trailing bytes."""

    payload = bytes(raw)
    chunks: list[XRayChunk] = []
    offset = 0
    while offset < len(payload):
        if len(payload) - offset < 8:
            raise _fail(f"chunk header обрезан на смещении 0x{offset:X}")
        chunk_type, size = struct.unpack_from("<II", payload, offset)
        data_start = offset + 8
        data_end = data_start + size
        if data_end > len(payload):
            raise _fail(
                f"chunk type={chunk_type} обрезан: конец 0x{data_end:X}, "
                f"payload заканчивается на 0x{len(payload):X}"
            )
        chunks.append(XRayChunk(chunk_type, offset, size, payload[data_start:data_end]))
        offset = data_end
    if not chunks:
        raise _fail("payload не содержит chunks")
    return tuple(chunks)


@dataclass(frozen=True)
class XRayContainer:
    """Validated original X-Ray container with a lossless no-op builder."""

    original: bytes
    magic: int
    version: int
    unpacked_size: int
    raw: bytes
    chunks: tuple[XRayChunk, ...]

    @classmethod
    def from_bytes(cls, data: bytes) -> XRayContainer:
        original = bytes(data)
        if len(original) < 12:
            raise _fail("заголовок короче 12 байт")

        magic, version, unpacked_size = struct.unpack_from("<III", original, 0)
        if magic != XRAY_MAGIC:
            raise _fail(f"неверная сигнатура 0x{magic:08X}, ожидалось 0xFFFFFFFF")
        if version not in XRAY_SUPPORTED_OUTER_VERSIONS:
            supported = ", ".join(str(value) for value in sorted(XRAY_SUPPORTED_OUTER_VERSIONS))
            raise _fail(f"неподдерживаемая версия контейнера {version}; поддерживаются {supported}")
        if unpacked_size <= 0 or unpacked_size > XRAY_MAX_UNPACKED_SIZE:
            raise _fail(f"недопустимый распакованный размер: {unpacked_size}")

        raw = lzo1x_decompress(original[12:], unpacked_size)
        chunks = parse_chunks(raw)
        return cls(original, magic, version, unpacked_size, raw, chunks)

    @property
    def chunk_types(self) -> tuple[int, ...]:
        return tuple(chunk.type for chunk in self.chunks)

    def build(self, raw: bytes | None = None) -> bytes:
        """Return original bytes for a no-op, or a valid rebuilt container."""

        if raw is None or bytes(raw) == self.raw:
            return self.original
        payload = bytes(raw)
        if not payload or len(payload) > XRAY_MAX_UNPACKED_SIZE:
            raise _fail(
                f"изменённый payload имеет недопустимый размер {len(payload)}"
            )
        parse_chunks(payload)
        return struct.pack("<III", self.magic, self.version, len(payload)) + lzo1x_compress(payload)


__all__ = [
    "XRAY_MAGIC",
    "XRAY_MAX_UNPACKED_SIZE",
    "XRAY_SUPPORTED_OUTER_VERSIONS",
    "XRayChunk",
    "XRayContainer",
    "XRayError",
    "lzo1x_compress",
    "lzo1x_decompress",
    "parse_chunks",
]

files.editor/xray_factions.py:
"""Resource-backed X-Ray community/faction catalog extraction.

The engine calls these identifiers ``communities``.  The catalog keeps the
engine spelling exactly as it appears in ``game_relations.ltx`` because that
same key is used by ``character_community()`` and by the string table.  No
cross-game list is kept here: every result comes from the selected release's
resource sections.
"""

from __future__ import annotations

from collections.abc import Iterable, Mapping
from pathlib import Path
from typing import Any

from .catalog import FactionCatalog, FactionDefinition


def _int_value(value: str | None) -> int | None:
    if value is None:
        return None
    try:
        return int(value.strip(), 0)
    except ValueError:
        try:
            return int(float(value.strip().replace(",", ".")))
        except ValueError:
            return None


def _community_pairs(value: str | None) -> tuple[tuple[str, int], ...]:
    if not value:
        return ()
    tokens = tuple(token.strip() for token in value.split(",") if token.strip())
    if len(tokens) < 2 or len(tokens) % 2:
        return ()
    pairs: list[tuple[str, int]] = []
    for index in range(0, len(tokens), 2):
        key = tokens[index]
        numeric_id = _int_value(tokens[index + 1])
        if not key or numeric_id is None:
            return ()
        pairs.append((key, numeric_id))
    return tuple(pairs)


def _relation_values(value: str | None) -> tuple[int, ...]:
    if not value:
        return ()
    values: list[int] = []
    for token in value.split(","):
        parsed = _int_value(token)
        if parsed is None:
            return ()
        values.append(parsed)
    return tuple(values)


def factions_from_sections(
    sections: Iterable[tuple[str, Any, Mapping[str, str]]],
    localization: Mapping[str, str],
    *,
    release_id: str,
    source_prefix: str = "",
    source_root: Path | None = None,
) -> FactionCatalog | None:
    """Build one faction catalog from resolved official LTX sections.

    ``sections`` has the same resolved-section shape used by the item reader:
    ``(section name, section object, inherited values)``.  Keeping this
    function independent of the filesystem/archive reader makes it usable for
    both unpacked resources and verified X-Ray archives.
    """

    communities: tuple[tuple[str, int], ...] = ()
    community_source = ""
    relation_rows: Mapping[str, str] = {}
    game_relations_values: Mapping[str, str] = {}
    action_points_values: Mapping[str, str] = {}
    for name, section, values in sections:
        lowered = name.casefold()
        if lowered == "game_relations":
            if not communities:
                parsed = _community_pairs(values.get("communities"))
                if parsed:
                    communities = parsed
                    community_source = f"{source_prefix}{getattr(section, 'source', '')}#communities"
            if not game_relations_values:
                game_relations_values = values
        elif lowered == "communities_relations" and not relation_rows:
            relation_rows = values
        elif lowered == "action_points" and not action_points_values:
            action_points_values = values

    if not communities:
        return None

    keys = tuple(key for key, _ in communities)
    source = community_source or "resource:game_relations#communities"
    factions = tuple(
        FactionDefinition(
            key=key,
            # X-Ray's UI translates CharacterInfo().Community().id() directly.
            # Missing language entries stay None instead of becoming guessed
            # English names or the key itself.
            display_name=localization.get(key),
            source=source,
            release_id=release_id,
            numeric_id=numeric_id,
        )
        for key, numeric_id in communities
    )

    relations: list[tuple[str, str, int]] = []
    for source_key in keys:
        row = _relation_values(relation_rows.get(source_key))
        if not row:
            continue
        for target_key, value in zip(keys, row, strict=False):
            relations.append((source_key, target_key, value))

    goodwill_limits = _relation_values(
        action_points_values.get("community_goodwill_limits")
    )
    return FactionCatalog(
        release_id=release_id,
        source_root=source_root,
        factions=factions,
        relations=tuple(relations),
        goodwill_min=goodwill_limits[0] if len(goodwill_limits) >= 2 else None,
        goodwill_max=goodwill_limits[1] if len(goodwill_limits) >= 2 else None,
        attitude_neutral_threshold=_int_value(
            game_relations_values.get("attitude_neutal_threshold")
        ),
        attitude_friend_threshold=_int_value(
            game_relations_values.get("attitude_friend_threshold")
        ),
    )


__all__ = ["factions_from_sections"]

files.editor/xray_catalog.py:
"""Read-only catalog extraction from an explicitly selected X-Ray install.

The reader understands the text conventions used by official X-Ray item
configuration: INI-like sections, inheritance, and XML localization.  It
also accepts a deliberately small uncompressed XDB reader for portable
fixtures.  Encrypted or compressed archive variants return no catalog until
their decoder is independently verified; serialized save keys remain visible
in that case.
"""

from __future__ import annotations

import binascii
import logging
import re
import struct
import xml.etree.ElementTree as ET
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from pathlib import Path

from .catalog import (
    GameCatalog,
    ItemCatalog,
    ItemDefinition,
    UpgradeCatalog,
    UpgradeDefinition,
)
from .catalog_bundle import CatalogBundleError, load_catalog_file
from .releases import ReleaseDescriptor
from .xray_container import lzo1x_decompress
from .xray_factions import factions_from_sections

LOGGER = logging.getLogger(__name__)

_SECTION_RE = re.compile(r"^\[([^\]]+)\](?::(.*))?$")
_INCLUDE_RE = re.compile(r"^#include\s+[\"']([^\"']+)[\"']", re.IGNORECASE)
_NUMERIC_KEYS = {
    "inv_weight",
    "inv_grid_width",
    "inv_grid_height",
    "inv_max_count",
    "box_size",
}
_KNOWN_MOD_MARKERS = ("ogsm", "srp", "anomaly", "misery", "complete")


@dataclass
class _Section:
    name: str
    bases: tuple[str, ...]
    values: dict[str, str]
    source: str
    entries: tuple[str, ...] = ()


class _ArchiveUnavailableError(Exception):
    pass


_LZHUF_N = 4096
_LZHUF_F = 60
_LZHUF_THRESHOLD = 2
_LZHUF_MAX_FREQ = 0x4000
_LZHUF_N_CHAR = 256 - _LZHUF_THRESHOLD + _LZHUF_F
_LZHUF_T = _LZHUF_N_CHAR * 2 - 1
_LZHUF_R = _LZHUF_T - 1
_LZHUF_D_CODE = tuple(
    [0] * 32
    + [1] * 16
    + [2] * 16
    + [3] * 16
    + [value for value in range(4, 12) for _ in range(8)]
    + [value for value in range(12, 24) for _ in range(4)]
    + [value for value in range(24, 48) for _ in range(2)]
    + list(range(48, 64))
)
_LZHUF_D_LEN = tuple([3] * 32 + [4] * 48 + [5] * 64 + [6] * 48 + [7] * 48 + [8] * 16)


def _lzhuf_decode(code: bytes) -> bytes:
    """Decode X-Ray's bounded LZ-Huffman header stream."""

    if len(code) < 4:
        raise _ArchiveUnavailableError("LZ-Huffman stream is truncated")
    text_size = struct.unpack_from("<I", code, 0)[0]
    if text_size > 64 * 1024 * 1024:
        raise _ArchiveUnavailableError("LZ-Huffman output is too large")
    freq = [0] * (_LZHUF_T + 1)
    son = [0] * _LZHUF_T
    parent = [0] * (_LZHUF_T + _LZHUF_N_CHAR)
    for index in range(_LZHUF_N_CHAR):
        freq[index] = 1
        son[index] = index + _LZHUF_T
        parent[index + _LZHUF_T] = index
    index = 0
    node = _LZHUF_N_CHAR
    while node <= _LZHUF_R:
        freq[node] = freq[index] + freq[index + 1]
        son[node] = index
        parent[index] = node
        parent[index + 1] = node
        index += 2
        node += 1
    freq[_LZHUF_T] = 0xFFFF
    parent[_LZHUF_R] = 0

    source_pos = 4
    bit_buffer = 0
    bit_count = 0

    def get_bit() -> int:
        nonlocal source_pos, bit_buffer, bit_count
        while bit_count <= 8:
            value = code[source_pos] if source_pos < len(code) else 0
            source_pos += 1
            bit_buffer = (bit_buffer | (value << (8 - bit_count))) & 0xFFFFFFFF
            bit_count += 8
        value = bit_buffer
        bit_buffer = (bit_buffer << 1) & 0xFFFFFFFF
        bit_count -= 1
        return (value >> 15) & 1

    def get_byte() -> int:
        nonlocal source_pos, bit_buffer, bit_count
        while bit_count <= 8:
            value = code[source_pos] if source_pos < len(code) else 0
            source_pos += 1
            bit_buffer = (bit_buffer | (value << (8 - bit_count))) & 0xFFFFFFFF
            bit_count += 8
        value = bit_buffer
        bit_buffer = (bit_buffer << 8) & 0xFFFFFFFF
        bit_count -= 8
        return (value & 0xFF00) >> 8

    def update(symbol: int) -> None:
        nonlocal freq, son, parent
        if freq[_LZHUF_R] == _LZHUF_MAX_FREQ:
            leaf = 0
            for node_index in range(_LZHUF_T):
                if son[node_index] >= _LZHUF_T:
                    freq[leaf] = (freq[node_index] + 1) // 2
                    son[leaf] = son[node_index]
                    leaf += 1
            left = 0
            right = _LZHUF_N_CHAR
            while right < _LZHUF_T:
                next_frequency = freq[left] + freq[left + 1]
                insert = right - 1
                while next_frequency < freq[insert]:
                    insert -= 1
                insert += 1
                for shift in range(right, insert, -1):
                    freq[shift] = freq[shift - 1]
                    son[shift] = son[shift - 1]
                freq[insert] = next_frequency
                son[insert] = left
                left += 2
                right += 1
            for node_index in range(_LZHUF_T):
                child = son[node_index]
                if child >= _LZHUF_T:
                    parent[child] = node_index
                else:
                    parent[child] = node_index
                    parent[child + 1] = node_index

        node = parent[symbol + _LZHUF_T]
        while True:
            next_frequency = freq[node] + 1
            freq[node] = next_frequency
            child = node + 1
            if next_frequency > freq[child]:
                while next_frequency > freq[child + 1]:
                    child += 1
                freq[node], freq[child] = freq[child], next_frequency
                left_child = son[node]
                parent[left_child] = child
                if left_child < _LZHUF_T:
                    parent[left_child + 1] = child
                right_child = son[child]
                son[child] = left_child
                parent[right_child] = node
                if right_child < _LZHUF_T:
                    parent[right_child + 1] = node
                son[node] = right_child
                node = child
            node = parent[node]
            if node == 0:
                break

    def decode_char() -> int:
        node = son[_LZHUF_R]
        while node < _LZHUF_T:
            node = son[node + get_bit()]
        symbol = node - _LZHUF_T
        update(symbol)
        return symbol

    output = bytearray()
    text_buffer = bytearray(b" " * (_LZHUF_N + _LZHUF_F - 1))
    write_pos = _LZHUF_N - _LZHUF_F
    while len(output) < text_size:
        symbol = decode_char()
        if symbol < 256:
            value = symbol
            output.append(value)
            text_buffer[write_pos] = value
            write_pos = (write_pos + 1) & (_LZHUF_N - 1)
            continue
        encoded_position = get_byte()
        distance = _LZHUF_D_CODE[encoded_position] << 6
        bit_length = _LZHUF_D_LEN[encoded_position] - 2
        shifted = encoded_position
        for _ in range(bit_length):
            shifted = (shifted << 1) + get_bit()
        distance |= shifted & 0x3F
        position = (write_pos - distance - 1) & (_LZHUF_N - 1)
        copy_length = symbol - 255 + _LZHUF_THRESHOLD
        for _ in range(copy_length):
            value = text_buffer[position]
            output.append(value)
            text_buffer[write_pos] = value
            position = (position + 1) & (_LZHUF_N - 1)
            write_pos = (write_pos + 1) & (_LZHUF_N - 1)
            if len(output) >= text_size:
                break
    return bytes(output)


def _xray_scramble_decrypt(data: bytes, *, world_wide: bool) -> bytes:
    """Undo the public X-Ray 2947 regional header scrambler."""

    seed = 0x16EB2EB if world_wide else 0x131A9D3
    seed0 = 0x5BBC4B if world_wide else 0x1329436
    size_multiplier = 4 if world_wide else 8
    sbox = list(range(256))
    for _ in range(size_multiplier * 256):
        seed0 = (1 + seed0 * 0x8088405) & 0xFFFFFFFF
        first = (seed0 >> 24) & 0xFF
        while True:
            seed0 = (1 + seed0 * 0x8088405) & 0xFFFFFFFF
            second = (seed0 >> 24) & 0xFF
            if first != second:
                break
        sbox[first], sbox[second] = sbox[second], sbox[first]
    inverse = [0] * 256
    for index, value in enumerate(sbox):
        inverse[value] = index
    output = bytearray(len(data))
    for index, value in enumerate(data):
        seed = (1 + seed * 0x8088405) & 0xFFFFFFFF
        output[index] = inverse[value ^ ((seed >> 24) & 0xFF)]
    return bytes(output)


def _decode(data: bytes) -> str:
    for encoding in ("utf-8-sig", "cp1251"):
        try:
            return data.decode(encoding)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", errors="replace")


def _strip_comment(line: str) -> str:
    quote: str | None = None
    for index, character in enumerate(line):
        if character in "\"'":
            if quote == character:
                quote = None
            elif quote is None:
                quote = character
        elif quote is None and character in ";":
            return line[:index]
    return line


def _parse_ltx(text: str, source: str) -> dict[str, _Section]:
    sections: dict[str, _Section] = {}
    current: _Section | None = None
    for raw_line in text.splitlines():
        line = _strip_comment(raw_line).strip()
        if not line:
            continue
        include = _INCLUDE_RE.match(line)
        if include:
            # Includes are expanded by the provider where a filesystem base
            # is available.  Keeping the directive out of values prevents it
            # from becoming a false item field in an archive entry.
            continue
        match = _SECTION_RE.match(line)
        if match:
            name = match.group(1).strip()
            bases = tuple(
                base.strip() for base in (match.group(2) or "").split(",") if base.strip()
            )
            current = _Section(name, bases, {}, source)
            sections[name] = current
            continue
        if current is None or "=" not in line:
            if current is not None:
                current.entries = (*current.entries, line)
            continue
        key, value = line.split("=", 1)
        key = key.strip().casefold()
        value = value.strip().strip("\"'").strip()
        current.values[key] = value
    return sections


def _parse_float(value: str | None) -> float | None:
    if value is None:
        return None
    try:
        return float(value.replace(",", "."))
    except ValueError:
        return None


def _parse_int(value: str | None) -> int | None:
    if value is None:
        return None
    try:
        return int(value, 0)
    except ValueError:
        try:
            return int(float(value.replace(",", ".")))
        except ValueError:
            return None


def _parse_slots(value: str | None) -> tuple[str, ...]:
    if value is None:
        return ()
    return tuple(
        token.strip() for token in re.split(r"[,; ]+", value) if token.strip()
    )


def _localization(root: Path, files: Mapping[str, bytes] | None = None) -> dict[str, str]:
    values: dict[str, str] = {}
    raw_files: Iterable[tuple[str, bytes]]
    if files is None:
        all_candidates = tuple(
            path
            for base in (
                root / "config" / "text",
                root / "configs" / "text",
                root / "text",
                root / "localization",
            )
            if base.is_dir()
            for path in base.rglob("*.xml")
            if path.is_file()
        )
        preferred = tuple(
            path
            for path in all_candidates
            if "/text/eng/" in f"/{path.as_posix().casefold()}/"
            or "/text/en/" in f"/{path.as_posix().casefold()}/"
            or "/localization/eng/" in f"/{path.as_posix().casefold()}/"
        )
        candidates = preferred or all_candidates
        raw_files = ((path.as_posix(), path.read_bytes()) for path in candidates)
    else:
        all_files = tuple(
            (name, data)
            for name, data in files.items()
            if name.casefold().endswith(".xml")
            and (
                "/text/" in f"/{name.casefold()}"
                or "/localization/" in f"/{name.casefold()}"
            )
        )
        preferred_files = tuple(
            (name, data)
            for name, data in all_files
            if "/text/eng/" in f"/{name.casefold()}/"
            or "/text/en/" in f"/{name.casefold()}/"
            or "/localization/eng/" in f"/{name.casefold()}/"
        )
        raw_files = (
            preferred_files or all_files
        )
    for name, data in raw_files:
        try:
            tree = ET.fromstring(data)
        except (ET.ParseError, ValueError):
            LOGGER.debug("Skipping malformed X-Ray localization file %s", name)
            continue
        for element in tree.iter():
            if element.tag.rsplit("}", 1)[-1] != "string":
                continue
            key = element.attrib.get("id")
            text = next(
                (
                    child.text.strip()
                    for child in element
                    if child.tag.rsplit("}", 1)[-1] == "text" and child.text
                ),
                None,
            )
            if key and text:
                values[key] = text
    return values


def _category(name: str, values: Mapping[str, str]) -> str | None:
    class_name = values.get("class", "").upper()
    lowered = name.casefold()
    if class_name == "AMMO" or lowered.startswith("ammo_"):
        return "ammo"
    if values.get("weapon_class") or values.get("ammo_class") or lowered.startswith(
        ("wpn_", "weapon_")
    ):
        return "weapon"
    if class_name.startswith("G_") or lowered.startswith(("grenade", "rgd", "f1_")):
        return "grenade"
    if lowered.startswith(("outfit_", "scientific_", "helm_", "armor_")):
        return "outfit"
    if lowered.startswith(("af_", "artifact_")):
        return "artifact"
    if lowered.startswith(
        ("medkit", "bandage", "antirad", "drug_", "food_", "bread", "kolbasa", "vodka", "energy")
    ):
        return "consumable"
    if "inv_name" in values or "inv_name_short" in values:
        return "item"
    return None


def _serialization_family(
    name: str,
    values: Mapping[str, str],
    category: str | None,
) -> str:
    """Map an official config definition to its STATE/UPDATE serializer.

    X-Ray's ``class`` values are object-factory identifiers, not save bytes.
    This deliberately maps only the class families whose serializer inheritance
    is visible in the public server sources.  Several gameplay categories
    (medkits, artifacts, food, grenades and generic devices) share the base
    inventory serializer and therefore use ``base``.
    """

    lowered = name.casefold()
    class_name = values.get("class", "").strip().upper()
    if category == "ammo" or class_name == "AMMO":
        return "ammo"
    if lowered == "device_torch":
        return "torch"
    if lowered == "device_pda":
        return "pda"
    if lowered.startswith(("detector_", "device_detector")):
        return "detector"
    if category == "weapon" or lowered.startswith(("wpn_", "weapon_")):
        if class_name in {"WP_KNIFE"} or lowered.endswith("_knife"):
            return "weapon"
        if class_name in {"WP_BM16", "WP_RG6", "WP_SHOTG", "WP_SPAS12", "WP_TOZ34"}:
            return "weapon_shotgun"
        if class_name in {"WP_AK74", "WP_FN2000", "WP_GROZA"}:
            return "weapon_wgl"
        if class_name.startswith("WP_"):
            return "weapon_magazined"
    if category == "outfit" or class_name in {
        "E_STLK",
        "E_SCI",
        "E_MILIT",
        "E_EXO",
    }:
        return "outfit"
    if class_name in {"II_PDA", "IITEM_PDA"}:
        return "pda"
    if class_name in {"II_DOCUMENT", "IITEM_DOCUMENT"}:
        return "document"
    return "base"


def _resolve_sections(sections: Mapping[str, _Section]) -> Iterable[tuple[str, _Section, dict[str, str]]]:
    cache: dict[str, dict[str, str]] = {}

    def resolve(name: str, stack: tuple[str, ...] = ()) -> dict[str, str]:
        if name in cache:
            return cache[name]
        if name in stack:
            return {}
        section = sections[name]
        values: dict[str, str] = {}
        for base in section.bases:
            if base in sections:
                values.update(resolve(base, (*stack, name)))
        values.update(section.values)
        cache[name] = values
        return values

    for name, section in sections.items():
        yield name, section, resolve(name)


def _items_from_sections(
    sections: Mapping[str, _Section],
    localization: Mapping[str, str],
    *,
    source_prefix: str = "",
) -> tuple[ItemDefinition, ...]:
    items: list[ItemDefinition] = []
    for name, section, values in _resolve_sections(sections):
        category = _category(name, values)
        if category is None or name.startswith("$"):
            continue
        name_key = values.get("inv_name_short") or values.get("inv_name")
        display_name = localization.get(name_key) if name_key else None
        max_stack = _parse_int(values.get("box_size"))
        if max_stack is None:
            max_stack = _parse_int(values.get("inv_max_count"))
        source = f"{source_prefix}{section.source}#{name}"
        items.append(
            ItemDefinition(
                key=name,
                display_name=display_name,
                category=category,
                unit_weight=_parse_float(values.get("inv_weight")),
                width=_parse_int(values.get("inv_grid_width")),
                height=_parse_int(values.get("inv_grid_height")),
                max_stack=max_stack,
                slots=_parse_slots(values.get("inv_grid_slot")),
                prototype=None,
                source=source,
                class_name=values.get("class"),
                serialization_family=_serialization_family(name, values, category),
                icon_x=_parse_int(values.get("inv_grid_x")),
                icon_y=_parse_int(values.get("inv_grid_y")),
                icon_texture=values.get("icons_texture") or "ui_icon_equipment",
            )
        )
    return tuple(items)


def _upgrade_item_key(source: str) -> str | None:
    """Map an official upgrade file name only when its convention is exact.

    Weapon files use ``w_<section>_up.ltx`` while outfit files use
    ``o_<section>_up.ltx``.  The resulting candidate is accepted only if it
    exists in the already parsed official item catalog; otherwise it remains
    unbound rather than becoming a guessed SID.
    """

    normalized = source.replace("\\", "/").casefold()
    filename = normalized.rsplit("/", 1)[-1]
    if not filename.endswith("_up.ltx"):
        return None
    stem = filename[: -len("_up.ltx")]
    if "/weapons/upgrades/" in normalized and stem.startswith("w_"):
        suffix = stem[2:]
        return f"wpn_{suffix}" if suffix else None
    if "/outfit_upgrades/" in normalized and stem.startswith("o_"):
        return stem[2:] or None
    if "/outfit_upgrades/" in normalized:
        # Call of Pripyat names helmet/outfit files directly, e.g.
        # ``helm_battle_up.ltx``.
        return stem or None
    return None


def _upgrades_from_sections(
    sections: Mapping[str, _Section],
    localization: Mapping[str, str],
    item_keys: set[str],
    *,
    release_id: str,
    source_root: Path | None,
) -> UpgradeCatalog | None:
    upgrades: list[UpgradeDefinition] = []
    aliases: set[str] = set()
    for name, section, _values in _resolve_sections(sections):
        if name.casefold() == "upgraded_inventory":
            aliases.update(section.entries)
    for name, section, values in _resolve_sections(sections):
        if not name.casefold().startswith("up_") or not values.get("section"):
            continue
        candidate_item = _upgrade_item_key(section.source)
        item_key = candidate_item if candidate_item in item_keys else None
        applicable_items = tuple(
            alias
            for alias in sorted(aliases)
            if candidate_item is not None
            and (alias == candidate_item or alias.startswith(f"{candidate_item}_"))
        )
        name_key = values.get("name")
        display_name = localization.get(name_key) if name_key else None
        upgrades.append(
            UpgradeDefinition(
                key=name,
                display_name=display_name or name_key,
                category=(
                    "weapon"
                    if "/weapons/upgrades/" in section.source.replace("\\", "/").casefold()
                    else "outfit"
                    if "/outfit_upgrades/" in section.source.replace("\\", "/").casefold()
                    else None
                ),
                item_key=item_key,
                source=f"{section.source}#{name}",
                release_id=release_id,
                section=values.get("section"),
                property_name=values.get("property"),
                icon=values.get("icon"),
                applicable_item_keys=applicable_items,
            )
        )
    if not upgrades:
        return None
    return UpgradeCatalog(release_id, source_root, tuple(upgrades))


def _read_xray_archive(
    path: Path,
    *,
    suffixes: tuple[str, ...] = (".ltx", ".xml"),
    names: frozenset[str] | None = None,
) -> dict[str, bytes]:
    """Read verified entries from one X-Ray DB archive.

    The normal catalog path asks only for config/localization text. The
    optional exact-name filter is used by the desktop icon resolver to read a
    single official DDS from an asset volume without unpacking or copying the
    archive into the repository.
    """

    file_size = path.stat().st_size
    header_data: bytes | None = None
    header_compressed = False
    data_start: int | None = None
    data_end = 0
    with path.open("rb") as handle:
        position = 0
        while position < file_size:
            handle.seek(position)
            raw_header = handle.read(8)
            if len(raw_header) != 8:
                raise _ArchiveUnavailableError("truncated X-Ray archive chunk")
            chunk_type, chunk_size = struct.unpack("<II", raw_header)
            body_offset = position + 8
            body_end = body_offset + chunk_size
            if body_end > file_size:
                raise _ArchiveUnavailableError("X-Ray archive chunk exceeds file")
            base_type = chunk_type & 0x7FFFFFFF
            if base_type == 0:
                if data_start is None:
                    data_start = body_offset
                data_end = max(data_end, body_end)
            elif base_type == 1:
                if header_data is not None:
                    raise _ArchiveUnavailableError("multiple X-Ray archive headers")
                handle.seek(body_offset)
                header_data = handle.read(chunk_size)
                header_compressed = bool(chunk_type & 0x80000000)
            elif base_type == 666:
                # Official ``resources/*.db`` archives begin with an INI-like
                # archive descriptor.  It is metadata, not the file data or
                # the file-index header.  OpenXRay names this chunk
                # ``CFS_HeaderChunkID``.
                pass
            position = body_end
    if header_data is None or data_start is None or data_end == 0:
        raise _ArchiveUnavailableError("X-Ray archive has no data/header chunks")

    decoded_headers: list[bytes] = []
    if not header_compressed:
        decoded_headers.append(header_data)
    else:
        # Some official archives (including the local CoP resources DB) use
        # the LZ-Huffman header directly.  Other generations apply the public
        # regional scrambler before LZ-Huffman.  Try the unencrypted form
        # first, then the verified scrambler variants.
        try:
            decoded_headers.append(_lzhuf_decode(header_data))
        except _ArchiveUnavailableError:
            for world_wide in (True, False):
                try:
                    decoded_headers.append(
                        _lzhuf_decode(
                            _xray_scramble_decrypt(header_data, world_wide=world_wide)
                        )
                    )
                except _ArchiveUnavailableError:
                    continue
    for header in decoded_headers:
        entries: list[tuple[str, int, int, int, int]] = []
        position = 0
        valid = True
        while position < len(header):
            if position + 14 > len(header):
                valid = False
                break
            name_size, real_size, compressed_size, crc = struct.unpack_from(
                "<HIII", header, position
            )
            position += 14
            name_length = name_size - 16
            if name_length < 0 or position + name_length > len(header):
                valid = False
                break
            name = _decode(header[position : position + name_length]).replace("\\", "/")
            position += name_length
            if position + 4 > len(header):
                valid = False
                break
            offset = struct.unpack_from("<I", header, position)[0]
            position += 4
            if offset and (
                offset < data_start or offset + compressed_size > data_end
            ):
                valid = False
                break
            entries.append((name, real_size, compressed_size, crc, offset))
        if not valid or not entries:
            continue

        files: dict[str, bytes] = {}
        with path.open("rb") as handle:
            for name, real_size, compressed_size, crc, offset in entries:
                lowered = name.casefold().replace("\\", "/").lstrip("/")
                if not offset or not lowered.endswith(suffixes):
                    continue
                if names is not None:
                    if not any(
                        lowered == candidate or lowered.endswith(f"/{candidate}")
                        for candidate in names
                    ):
                        continue
                elif not any(
                    marker in lowered
                    for marker in ("config/", "configs/", "localization/")
                ):
                    continue
                if offset + compressed_size > file_size:
                    valid = False
                    break
                handle.seek(offset)
                raw = handle.read(compressed_size)
                if len(raw) != compressed_size:
                    valid = False
                    break
                if compressed_size != real_size:
                    try:
                        raw = lzo1x_decompress(raw, real_size)
                    except Exception:
                        valid = False
                        break
                if len(raw) != real_size:
                    valid = False
                    break
                if crc and (binascii.crc32(raw) & 0xFFFFFFFF) != crc:
                    valid = False
                    break
                files[name] = bytes(raw)
        if valid and files:
            return files
    raise _ArchiveUnavailableError("no verified X-Ray archive header variant")


def _candidate_asset_archives(root: Path) -> tuple[Path, ...]:
    """Return official asset volumes without scanning unrelated game files."""

    candidates: set[Path] = set()
    for candidate_root in (root, root / "resources"):
        try:
            entries = tuple(candidate_root.iterdir())
        except OSError:
            continue
        for path in entries:
            if not path.is_file():
                continue
            name = path.name.casefold()
            if name.startswith(("resources.db", "gamedata.db")):
                candidates.add(path)
    return tuple(sorted(candidates, key=lambda path: path.as_posix().casefold()))


def read_xray_asset(root: Path, relative: str) -> bytes | None:
    """Read one exact official asset from a packed installation, if present."""

    normalized = relative.replace("\\", "/").lstrip("/").casefold()
    if not normalized.endswith(".dds"):
        normalized = f"{normalized}.dds"
    candidates = frozenset({normalized, f"gamedata/{normalized}"})
    for archive in _candidate_asset_archives(Path(root)):
        try:
            files = _read_xray_archive(
                archive,
                suffixes=(".dds",),
                names=candidates,
            )
        except (_ArchiveUnavailableError, OSError, ValueError):
            continue
        for name, data in files.items():
            lowered = name.replace("\\", "/").lstrip("/").casefold()
            if lowered == normalized or lowered.endswith(f"/{normalized}"):
                return data
    return None


def _candidate_archives(root: Path) -> tuple[Path, ...]:
    roots = (root, root / "resources", root / "localization")
    candidates: set[Path] = set()
    for candidate_root in roots:
        try:
            entries = tuple(candidate_root.iterdir())
        except OSError:
            continue
        for path in entries:
            if not path.is_file():
                continue
            name = path.name.casefold()
            # ``resources.db0`` ... ``resources.dbN`` are the large binary
            # asset volumes.  The official config/localization catalogs live
            # in the named index archives below; scanning every asset volume
            # would make a catalog lookup needlessly expensive and can expose
            # no additional LTX/XML entries.
            is_localization_volume = (
                candidate_root.name.casefold() == "localization"
                and name.startswith("x")
                and name.endswith(".db")
            )
            if (
                name.startswith(("gamedata.db", "gamedata.xdb"))
                or name in {"resources.db", "configs.db", "xenglish.db", "xrussian.db"}
                or is_localization_volume
            ):
                candidates.add(path)
    return tuple(sorted(candidates, key=lambda path: path.as_posix().casefold()))


def _has_obvious_mod_overlay(data_root: Path) -> bool:
    """Reject well-known community overlays under the official-only scope."""

    try:
        for path in data_root.rglob("*"):
            if any(marker in path.name.casefold() for marker in _KNOWN_MOD_MARKERS):
                return True
    except OSError:
        return True
    return False


class XRayCatalogProvider:
    """Load a catalog from one explicit original X-Ray installation root."""

    def __init__(self) -> None:
        self._catalog: ItemCatalog | None = None
        self._game_catalog: GameCatalog | None = None

    def load(
        self,
        release: ReleaseDescriptor,
        game_root: Path | None = None,
        *,
        allowed_editions: frozenset[str] = frozenset({"original"}),
    ) -> ItemCatalog | None:
        self._catalog = None
        self._game_catalog = None
        # ``allowed_editions`` stays original-only for every runtime caller, so
        # save editing is unaffected.  The icon-pack builder opts Enhanced
        # Editions in to harvest their HD atlases; EE ships the same item keys
        # and inventory grid, so the crops line up with the classic layout.
        if (
            release.family not in {"soc", "clear_sky", "cop"}
            or release.edition not in allowed_editions
        ):
            return None
        if game_root is None:
            return None
        root = Path(game_root).expanduser()
        if not root.is_dir():
            return None

        data_root = root / "gamedata"
        section_sources: dict[str, _Section] = {}
        localization: dict[str, str] = {}
        use_unpacked = data_root.is_dir() and not _has_obvious_mod_overlay(data_root)
        source_root = data_root if use_unpacked else root
        if use_unpacked:
            for path in sorted(data_root.rglob("*.ltx"), key=lambda value: value.as_posix().casefold()):
                try:
                    parsed = _parse_ltx(_decode(path.read_bytes()), path.relative_to(root).as_posix())
                except OSError:
                    continue
                section_sources.update(parsed)
            localization = _localization(data_root)

        items = _items_from_sections(section_sources, localization)
        if not items:
            # No unpacked catalog (or a textures-only gamedata tree, as the
            # Enhanced Editions ship): read the packed official archives.
            if not use_unpacked and data_root.is_dir():
                LOGGER.info(
                    "Ignoring an obvious community mod overlay in %s; "
                    "trying packed official resources",
                    data_root,
                )
            files: dict[str, bytes] = {}
            for archive in _candidate_archives(root):
                try:
                    files.update(_read_xray_archive(archive))
                except (_ArchiveUnavailableError, OSError, ValueError) as exc:
                    LOGGER.info("Skipping X-Ray archive %s: %s", archive.name, exc)
            if not files:
                return None
            section_sources = {}
            for name, raw in files.items():
                if name.casefold().endswith(".ltx"):
                    section_sources.update(_parse_ltx(_decode(raw), name))
            localization = _localization(root, files)
            source_root = root
            items = _items_from_sections(section_sources, localization)
        if not items:
            return None
        self._catalog = ItemCatalog(release.id, source_root, items)
        upgrades = _upgrades_from_sections(
            section_sources,
            localization,
            {item.key for item in items},
            release_id=release.id,
            source_root=source_root,
        )
        factions = factions_from_sections(
            _resolve_sections(section_sources),
            localization,
            release_id=release.id,
            source_root=source_root,
        )
        if factions is not None:
            self._game_catalog = GameCatalog(
                release.id,
                self._catalog,
                factions,
                upgrades,
            )
        return self._catalog

    def load_bundle(
        self,
        release: ReleaseDescriptor,
        game_root: Path | None = None,
    ) -> GameCatalog | None:
        """Load items and release-scoped communities from one official root."""

        self.load(release, game_root)
        return self._game_catalog

    def load_generated_bundle(
        self,
        release: ReleaseDescriptor,
        catalog_path: Path | None = None,
    ) -> GameCatalog | None:
        """Load the checked-in official metadata snapshot as a safe fallback.

        This path is used only after an explicit official installation root
        yielded no resource catalog.  It contains keys and UI metadata, not
        prototypes, game archives or save bytes, so it cannot manufacture a
        new serializer family or an unknown save reference.
        """

        if release.family not in {"soc", "clear_sky", "cop"} or release.edition != "original":
            return None
        path = catalog_path or Path(__file__).resolve().parents[1] / "web" / "catalogs.json"
        try:
            bundles = load_catalog_file(Path(path))
        except (CatalogBundleError, OSError, ValueError):
            return None
        bundle = bundles.get(release.id)
        return bundle.game_catalog if bundle is not None else None

    def resolve(self, key: str) -> ItemDefinition | None:
        return self._catalog.resolve(key) if self._catalog is not None else None


__all__ = ["XRayCatalogProvider", "read_xray_asset"]

files.editor/xray_delete.py:
"""Reference-safety preflight for structural X-Ray object deletion.

The original trilogy's save registry exposes a proven ``parent_id`` edge for
each parsed object.  A delete is safe to serialize only when the selected
object is actor-owned, is not explicitly equipped, and has no parsed registry
children.  This module deliberately reports a conservative decision; it does
not infer references from opaque state bytes.
"""

from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from .xray_save import XRayObject, XRaySave


@dataclass(frozen=True)
class XRayDeleteAnalysis:
    """Read-only result of the known-reference deletion checks."""

    object_id: int
    allowed: bool
    blockers: tuple[str, ...]
    dependent_ids: tuple[int, ...]

    @property
    def message(self) -> str:
        """Return a stable human-readable explanation for the UI/writer."""

        if self.blockers:
            return "; ".join(self.blockers)
        return "object is an actor-owned leaf inventory record"


def analyze_xray_delete(parsed: XRaySave, object_id: int) -> XRayDeleteAnalysis:
    """Check whether a parsed object may be structurally detached.

    Missing objects are returned as a blocked analysis instead of being
    mistaken for an empty registry slot.  ``storage is None`` remains
    compatible with the legacy fixture/writer path: it means placement was
    not decoded, not that the object is known to be equipped.
    """

    target = next(
        (obj for obj in parsed.objects if obj.object_id == object_id),
        None,
    )
    if target is None:
        return XRayDeleteAnalysis(
            object_id=object_id,
            allowed=False,
            blockers=("target object is unresolved or missing",),
            dependent_ids=(),
        )

    dependent_ids = tuple(
        sorted(
            obj.object_id
            for obj in parsed.objects
            if obj.object_id != target.object_id
            and obj.parent_id == target.object_id
        )
    )
    return _analysis_for_target(parsed, target, dependent_ids)


def analyze_xray_deletes(
    parsed: XRaySave,
    object_ids: Iterable[int],
) -> dict[int, XRayDeleteAnalysis]:
    """Analyze several targets with one pass over the object registry."""

    requested = tuple(dict.fromkeys(int(object_id) for object_id in object_ids))
    target_by_id = {
        obj.object_id: obj
        for obj in parsed.objects
        if obj.object_id in requested
    }
    dependents: dict[int, list[int]] = {object_id: [] for object_id in requested}
    for obj in parsed.objects:
        children = dependents.get(obj.parent_id)
        if children is not None and obj.object_id != obj.parent_id:
            children.append(obj.object_id)

    analyses: dict[int, XRayDeleteAnalysis] = {}
    for object_id in requested:
        target = target_by_id.get(object_id)
        if target is None:
            analyses[object_id] = XRayDeleteAnalysis(
                object_id=object_id,
                allowed=False,
                blockers=("target object is unresolved or missing",),
                dependent_ids=(),
            )
            continue
        analyses[object_id] = _analysis_for_target(
            parsed,
            target,
            tuple(sorted(dependents[object_id])),
        )
    return analyses


def _analysis_for_target(
    parsed: XRaySave,
    target: XRayObject,
    dependent_ids: tuple[int, ...],
) -> XRayDeleteAnalysis:
    """Build one decision after target/dependent lookup is complete."""

    blockers: list[str] = []
    if target.object_id == parsed.actor_id:
        blockers.append("target is actor")
    elif target.parent_id != parsed.actor_id:
        blockers.append("object is not actor-owned")
    if target.storage == "equipped":
        blockers.append("equipped object cannot be deleted")
    if target.object_id in parsed.unresolved_handles:
        blockers.append("object is unresolved")
    if dependent_ids:
        formatted = ", ".join(f"0x{value:04X}" for value in dependent_ids)
        blockers.append(f"object has dependent registry children: {formatted}")

    return XRayDeleteAnalysis(
        object_id=target.object_id,
        allowed=not blockers,
        blockers=tuple(blockers),
        dependent_ids=dependent_ids,
    )


__all__ = ["XRayDeleteAnalysis", "analyze_xray_delete", "analyze_xray_deletes"]

files.editor/xray_relations.py:
"""Bounded reader/writer for the original X-Ray relation registry.

The relation registry is part of the ALife registry container (chunk ``9``),
not part of the inventory object list.  Its first two maps are stable in the
official SoC, Clear Sky and CoP serializers: an InfoPortions map followed by a
character-id to ``RELATION_DATA`` map.  This module deliberately stops at the
end of that second map and preserves every later registry byte verbatim.
"""

from __future__ import annotations

import struct
from dataclasses import dataclass

from .xray_container import XRayError

_MAX_COUNT = 1_000_000
_MAX_STRING = 1 << 20


class XRayRelationError(XRayError):
    """Raised when the relation registry does not match an official layout."""


def _fail(message: str) -> XRayRelationError:
    return XRayRelationError(f"X-Ray relation registry: {message}")


class _Reader:
    def __init__(self, data: bytes) -> None:
        self.data = bytes(data)
        self.pos = 0

    def _take(self, size: int) -> bytes:
        if size < 0 or self.pos + size > len(self.data):
            raise _fail(f"данные обрезаны на смещении 0x{self.pos:X}")
        start = self.pos
        self.pos += size
        return self.data[start : self.pos]

    def _unpack(self, fmt: str) -> int:
        size = struct.calcsize(fmt)
        if self.pos + size > len(self.data):
            raise _fail(f"числовое поле обрезано на смещении 0x{self.pos:X}")
        value = struct.unpack_from(fmt, self.data, self.pos)[0]
        self.pos += size
        return int(value)

    def u16(self) -> int:
        return self._unpack("<H")

    def u32(self) -> int:
        return self._unpack("<I")

    def s32(self) -> int:
        return self._unpack("<i")

    def u64(self) -> int:
        return self._unpack("<Q")

    def zstring(self) -> str:
        end = self.data.find(b"\x00", self.pos)
        if end < 0 or end - self.pos > _MAX_STRING:
            raise _fail("строка InfoPortion не найдена или слишком длинная")
        value = self.data[self.pos : end]
        self.pos = end + 1
        return value.decode("utf-8", errors="replace")


@dataclass(frozen=True)
class XRayGoodwillEntry:
    """One community goodwill value and its exact serialized value offset."""

    community_index: int
    value: int
    value_offset: int


@dataclass(frozen=True)
class XRayRelationEntry:
    """One character row in the relation registry."""

    character_id: int
    personal: tuple[tuple[int, int], ...]
    communities: tuple[XRayGoodwillEntry, ...]
    record_start: int
    record_end: int
    community_count_offset: int

    def community(self, community_index: int) -> XRayGoodwillEntry | None:
        return next(
            (
                entry
                for entry in self.communities
                if entry.community_index == community_index
            ),
            None,
        )


@dataclass(frozen=True)
class XRayRelationRegistry:
    """Parsed prefix of chunk 9 with no ownership of its raw tail."""

    release_id: str
    info_end_offset: int
    relation_count: int
    entries: tuple[XRayRelationEntry, ...]
    relations_end_offset: int

    def for_character(self, character_id: int) -> XRayRelationEntry:
        for entry in self.entries:
            if entry.character_id == character_id:
                return entry
        raise XRayRelationError(
            f"character id 0x{character_id:04X} отсутствует в relation registry"
        )


def _read_count(reader: _Reader, label: str) -> int:
    count = reader.u32()
    if count > _MAX_COUNT:
        raise _fail(f"{label} count={count} слишком велик")
    return count


def parse_relation_registry(payload: bytes, release_id: str) -> XRayRelationRegistry:
    """Parse InfoPortions and the following relation map from chunk 9."""

    reader = _Reader(payload)
    info_count = _read_count(reader, "InfoPortions")
    with_info_time = release_id != "stalker-cop"
    for _ in range(info_count):
        reader.u16()  # InfoPortion registry key
        values_count = _read_count(reader, "InfoPortion vector")
        for _ in range(values_count):
            reader.zstring()
            if with_info_time:
                reader.u64()
    info_end_offset = reader.pos

    relation_count = _read_count(reader, "relation")
    entries: list[XRayRelationEntry] = []
    seen_characters: set[int] = set()
    for _ in range(relation_count):
        record_start = reader.pos
        character_id = reader.u16()
        if character_id in seen_characters:
            raise _fail(f"повторяющийся character id 0x{character_id:04X}")
        seen_characters.add(character_id)

        personal_count = _read_count(reader, "personal relation")
        personal: list[tuple[int, int]] = []
        seen_personal: set[int] = set()
        for _ in range(personal_count):
            target_id = reader.u16()
            value = reader.s32()
            if target_id in seen_personal:
                raise _fail(
                    f"character 0x{character_id:04X}: повторяющийся personal id "
                    f"0x{target_id:04X}"
                )
            seen_personal.add(target_id)
            personal.append((target_id, value))

        community_count_offset = reader.pos
        community_count = _read_count(reader, "community relation")
        communities: list[XRayGoodwillEntry] = []
        seen_communities: set[int] = set()
        for _ in range(community_count):
            community_index = reader.s32()
            value_offset = reader.pos
            value = reader.s32()
            if community_index in seen_communities:
                raise _fail(
                    f"character 0x{character_id:04X}: повторяющийся community "
                    f"{community_index}"
                )
            seen_communities.add(community_index)
            communities.append(
                XRayGoodwillEntry(community_index, value, value_offset)
            )
        entries.append(
            XRayRelationEntry(
                character_id=character_id,
                personal=tuple(personal),
                communities=tuple(communities),
                record_start=record_start,
                record_end=reader.pos,
                community_count_offset=community_count_offset,
            )
        )

    return XRayRelationRegistry(
        release_id=release_id,
        info_end_offset=info_end_offset,
        relation_count=relation_count,
        entries=tuple(entries),
        relations_end_offset=reader.pos,
    )


def patch_relation_registry(
    payload: bytes,
    registry: XRayRelationRegistry,
    *,
    character_id: int,
    community_index: int,
    goodwill: int,
) -> bytes:
    """Patch one goodwill or extend only the actor's existing relation row."""

    if not -0x80000000 <= goodwill <= 0x7FFFFFFF:
        raise _fail("goodwill не помещается в signed s32")
    if not -0x80000000 <= community_index <= 0x7FFFFFFF:
        raise _fail("community index не помещается в signed s32")
    entry = registry.for_character(character_id)
    raw = bytes(payload)
    if not 0 <= entry.record_start < entry.record_end <= len(raw):
        raise _fail("граница relation record выходит за chunk")
    existing = entry.community(community_index)
    if existing is not None:
        if existing.value_offset + 4 > len(raw):
            raise _fail("goodwill value offset выходит за chunk")
        result = bytearray(raw)
        struct.pack_into("<i", result, existing.value_offset, goodwill)
        return bytes(result)

    new_communities = sorted(
        [
            (community.community_index, community.value)
            for community in entry.communities
        ]
        + [(community_index, goodwill)],
        key=lambda value: value[0],
    )
    if not (
        entry.record_start <= entry.community_count_offset <= entry.record_end
    ):
        raise _fail("community count offset выходит за relation record")
    prefix = raw[entry.record_start : entry.community_count_offset]
    replacement = struct.pack("<I", len(new_communities)) + b"".join(
        struct.pack("<ii", index, value) for index, value in new_communities
    )
    return (
        raw[: entry.record_start]
        + prefix
        + replacement
        + raw[entry.record_end :]
    )


__all__ = [
    "XRayGoodwillEntry",
    "XRayRelationEntry",
    "XRayRelationError",
    "XRayRelationRegistry",
    "parse_relation_registry",
    "patch_relation_registry",
]
